<?php use App\Core\Csrf;use App\Core\Util;$t=['facebook'=>0,'offerup'=>0,'craigslist'=>0,'approved'=>0,'rejected'=>0,'pending'=>0];foreach($posts as$p){$t[$p['platform']]++;$t[$p['admin_review_status']]++;}?>
<div class="page-head"><div><div class="eyebrow">Daily Review</div><h1><?=Util::e($salesUser['display_name'])?> — <?=Util::e($date)?></h1></div></div>
<div class="metrics"><div class="metric"><strong><?=count($posts)?></strong><span>Total</span></div><div class="metric"><strong><?=$t['facebook']?></strong><span>Facebook</span></div><div class="metric"><strong><?=$t['offerup']?></strong><span>OfferUp</span></div><div class="metric"><strong><?=$t['craigslist']?></strong><span>Craigslist</span></div><div class="metric"><strong><?=$t['approved']?></strong><span>Approved</span></div><div class="metric"><strong><?=$t['rejected']?></strong><span>Rejected</span></div></div>
<div class="two"><div class="panel"><h2>Posts</h2><?php foreach($posts as$p):?><div class="mini"><span class="platform <?=Util::e($p['platform'])?>"><?=Util::e(ucfirst($p['platform']))?></span><div><b><?=Util::e($p['title'])?></b><small><?=Util::e($p['published_at'])?></small></div><span class="status <?=Util::e($p['admin_review_status'])?>"><?=Util::e(ucfirst($p['admin_review_status']))?></span></div><?php endforeach;?></div>
<div class="panel"><h2>Daily Rating & Note</h2><form method="post" enctype="multipart/form-data" action="<?=$config['app']['base_path']?>/admin/daily/review"><input type="hidden" name="_csrf" value="<?=Util::e(Csrf::token())?>"><input type="hidden" name="sales_user_id" value="<?=(int)$salesUser['id']?>"><input type="hidden" name="work_date" value="<?=Util::e($date)?>">
<label>Rating</label><select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>" <?=((int)($review['rating']??5)===$i)?'selected':''?>><?=str_repeat('★',$i)?> (<?=$i?>)</option><?php endfor;?></select><label>Daily Note</label><textarea name="note" rows="8"><?=Util::e($review['note']??'')?></textarea><label>Images</label><input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple><button class="btn primary">Save Daily Review</button></form></div></div>
